"use client";

import { FormEvent, useState } from "react";
import { Note } from "@/types/candidate";

interface NotesPanelProps {
  notes: Note[];
  loading: boolean;
  saving: boolean;
  deletingNoteId: string | null;
  onCreate: (content: string) => Promise<boolean>;
  onDelete: (noteId: string) => Promise<boolean>;
  error: string;
  success: string;
}

export function NotesPanel({ notes, loading, saving, deletingNoteId, onCreate, onDelete, error, success }: NotesPanelProps) {
  const [content, setContent] = useState("");

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();

    const normalizedContent = content.trim();
    if (normalizedContent.length < 3) {
      return;
    }

    const created = await onCreate(normalizedContent);
    if (created) {
      setContent("");
    }
  }

  return (
    <section className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm">
      <h2 className="text-lg font-semibold text-slate-900">Notas del proceso</h2>

      <form className="mt-4 flex flex-col gap-3" onSubmit={handleSubmit}>
        <textarea
          value={content}
          onChange={(event) => setContent(event.target.value)}
          placeholder="Agregar nota de seguimiento"
          className="min-h-24 w-full rounded-lg border border-slate-300 px-3 py-2 text-sm text-slate-900 focus:border-cyan-500 focus:outline-none"
        />
        <button
          type="submit"
          disabled={saving}
          className="w-fit rounded-lg bg-slate-900 px-4 py-2 text-sm font-semibold text-white transition hover:bg-slate-700 disabled:cursor-not-allowed disabled:opacity-60"
        >
          {saving ? "Guardando nota..." : "Agregar nota"}
        </button>
      </form>

      {error ? <p className="mt-3 rounded-lg bg-rose-50 px-3 py-2 text-sm text-rose-700">{error}</p> : null}
      {success ? <p className="mt-3 rounded-lg bg-emerald-50 px-3 py-2 text-sm text-emerald-700">{success}</p> : null}

      {loading ? <p className="mt-4 text-sm text-slate-500">Cargando notas...</p> : null}

      {!loading && notes.length === 0 ? (
        <p className="mt-4 text-sm text-slate-500">No hay notas para esta candidatura.</p>
      ) : null}

      <ul className="mt-4 space-y-3">
        {notes.map((note) => (
          <li key={note.id} className="rounded-xl border border-slate-200 bg-slate-50 p-4">
            <p className="text-sm text-slate-700">{note.content}</p>
            <div className="mt-3 flex items-center justify-between gap-3">
              <p className="text-xs text-slate-500">{new Date(note.created_at).toLocaleString("es-ES")}</p>
              <button
                type="button"
                onClick={async () => {
                  await onDelete(note.id);
                }}
                disabled={deletingNoteId === note.id}
                className="rounded-md border border-rose-300 px-2.5 py-1 text-xs font-semibold text-rose-700 transition hover:bg-rose-50 disabled:cursor-not-allowed disabled:opacity-60"
              >
                {deletingNoteId === note.id ? "Eliminando..." : "Eliminar"}
              </button>
            </div>
          </li>
        ))}
      </ul>
    </section>
  );
}
